def binom_fact(n: int, k: int) -> int:
    if k < 0 or k > n:
        return 0
    a = 1
    for i in range(2, n + 1):
        a *= i
    b = 1
    for i in range(2, k + 1):
        b *= i
    c = 1
    for i in range(2, n - k + 1):
        c *= i
    return a // (b * c)

def binom_mult(n: int, k: int) -> int:
    if k < 0 or k > n:
        return 0
    k = min(k, n - k)
    c = 1
    for i in range(k):
        c = c * (n - i) // (i + 1)
    return c
